n=24; out=[[0]*n for _ in range(n)]
for k in range(4,24,5):
 for i in range(n): out[k][i]=5; out[i][k]=5
shape=[(0,2),(1,0),(1,1),(1,2),(1,3),(2,1),(2,2),(3,2)]
# Wait input template rows5-8 cols10-13: row0 has col2; row1 has cols0-3; row2 has cols1,2; row3 has col2.
